import React from 'react';
import './Banner.css'; // Make sure you have this CSS file or use inline styles

function Banner({ selectedCategory, setSelectedCategory }) {
  const categories = ["ALL", "Men", "Women", "Kids", "Gadgets", "Books"];

  return (
    <div className="bannerParentDiv" style={{ borderBottom: '1px solid #ddd', backgroundColor: '#fff', padding: '10px 0' }}>
      <div className="bannerChildDiv" style={{ maxWidth: '1200px', margin: '0 auto', padding: '0 20px' }}>
        <div className="menu" style={{ display: 'flex', gap: '20px', overflowX: 'auto', whiteSpace: 'nowrap' }}>
          
          {categories.map((cat) => (
            <span
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              style={{
                cursor: 'pointer',
                fontWeight: selectedCategory === cat ? 'bold' : 'normal',
                color: selectedCategory === cat ? '#002f34' : '#555',
                borderBottom: selectedCategory === cat ? '3px solid #002f34' : '3px solid transparent',
                paddingBottom: '5px',
                fontSize: '15px'
              }}
            >
              {cat === "ALL" ? "All Categories" : cat}
            </span>
          ))}

        </div>
      </div>
    </div>
  );
}

export default Banner;
